CREATE OR REPLACE FUNCTION trip_private.night_checkin_tasks(p_trip uuid,p_week integer) RETURNS TABLE(id uuid,user_id uuid,title text,mission_text text,presented_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $fn$ BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) OR NOT EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=p_week AND NOT n.skipped AND now() BETWEEN n.starts_at-interval '12 hours' AND n.starts_at+interval '3 hours 30 minutes') THEN RAISE EXCEPTION 'Join this game night first'; END IF; RETURN QUERY SELECT c.id,c.user_id,c.title,c.mission_text,c.presented_at FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.phase='checkin' AND c.status='pending' ORDER BY c.created_at; END $fn$; REVOKE ALL ON FUNCTION trip_private.night_checkin_tasks(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION trip_private.night_checkin_tasks(uuid,integer) TO authenticated; CREATE OR REPLACE FUNCTION public.night_checkin_tasks(p_trip uuid,p_week integer) RETURNS TABLE(id uuid,user_id uuid,title text,mission_text text,presented_at timestamptz) LANGUAGE sql SET search_path=public AS $fn$ SELECT * FROM trip_private.night_checkin_tasks(p_trip,p_week) $fn$; REVOKE ALL ON FUNCTION public.night_checkin_tasks(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.night_checkin_tasks(uuid,integer) TO authenticated;